"""Intent tests for risk.summary_stats (RISK-04, TC-07): the annualized whole-period summary."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _summaries_by_ticker(contract_fake, golden) -> tuple[dict[str, TickerSummary], dict]:
    fake = contract_fake("risk.vol_series")
    given, expected = golden("risk", "TC-07")
    vol = fake.vol_from_json(given["vol"])
    result = summary_stats(vol)
    return {row.ticker: row for row in result}, expected


@pytest.mark.intent
def test_tc07_one_summary_per_ticker(contract_fake, golden):
    by_ticker, expected = _summaries_by_ticker(contract_fake, golden)
    assert all(isinstance(row, TickerSummary) for row in by_ticker.values())
    assert set(by_ticker) == {row["ticker"] for row in expected["summary"]}


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_statistics(contract_fake, golden, field):
    by_ticker, expected = _summaries_by_ticker(contract_fake, golden)
    for row in expected["summary"]:
        actual = getattr(by_ticker[row["ticker"]], field)
        assert actual == pytest.approx(row[field], abs=expected["tol"]), row["ticker"]


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(contract_fake, golden):
    by_ticker, expected = _summaries_by_ticker(contract_fake, golden)
    flat = [row for row in expected["summary"] if row["ann_vol"] == 0]
    assert flat
    for row in flat:
        got = by_ticker[row["ticker"]]
        assert got.ann_vol == pytest.approx(0.0, abs=expected["tol"])
        assert got.sharpe == pytest.approx(row["sharpe"], abs=expected["tol"])


@pytest.mark.intent
def test_tc07_last_rolling_volatility(contract_fake, golden):
    by_ticker, expected = _summaries_by_ticker(contract_fake, golden)
    for row in expected["summary"]:
        got = by_ticker[row["ticker"]].last_vol
        assert got is not None
        assert got == pytest.approx(row["last_vol"], abs=expected["tol"]), row["ticker"]


@pytest.mark.intent
def test_fewer_than_two_returns_raises(contract_fake, contract_sample):
    fake = contract_fake("risk.vol_series")
    vol = fake.vol_from_json(contract_sample("risk.VolSeries"))
    one = Returns(
        base_date=vol.returns.base_date,
        dates=vol.returns.dates[:1],
        tickers=vol.returns.tickers,
        values={t: vol.returns.values[t][:1] for t in vol.returns.tickers},
    )
    short = VolSeries(
        returns=one,
        window=vol.window,
        annualized=vol.annualized,
        values={t: (None,) for t in vol.returns.tickers},
    )
    with pytest.raises(ValueError, match=r"(?i)two|2"):
        summary_stats(short)

